css:
.succession-sim-container {
    padding: 28px 32px;
    background: #f8f9fa;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', sans-serif;
    color: #1a2744;
    max-width: 1100px;
    margin: 0 auto;
}
.succession-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 100%);
    color: #ffffff;
    padding: 32px 36px;
    margin-bottom: 24px;
    border-radius: 4px;
    border-bottom: 3px solid #c9a84c;
}
.succession-sim-header-badge {
    display: inline-block;
    background: rgba(201,168,76,0.2);
    border: 1px solid #c9a84c;
    color: #c9a84c;
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 4px 12px;
    border-radius: 2px;
    margin-bottom: 12px;
}
.succession-sim-header h1 {
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    letter-spacing: -0.01em;
}
.succession-sim-subtitle {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.7);
    margin: 0;
}
.succession-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #5a6c7d;
    padding: 12px;
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    margin-bottom: 20px;
    font-weight: 600;
}
.succession-sim-period-counter span {
    margin: 0 3px;
}
.succession-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.succession-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    padding: 18px 16px;
    position: relative;
    transition: box-shadow 0.2s ease;
}
.succession-sim-kpi-card:hover {
    box-shadow: 0 2px 8px rgba(26,39,68,0.08);
}
.succession-sim-kpi-highlight {
    border: 2px solid #1a2744;
    background: #f0f2f8;
}
.succession-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #5a6c7d;
    margin-bottom: 6px;
    font-weight: 600;
}
.succession-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 8px;
}
.succession-sim-kpi-bar {
    height: 4px;
    background: #e9ecef;
    border-radius: 2px;
    overflow: hidden;
}
.succession-sim-kpi-fill {
    height: 100%;
    border-radius: 2px;
    transition: width 0.4s ease;
}
.succession-sim-fill-blue { background: #3b82f6; }
.succession-sim-fill-green { background: #22c55e; }
.succession-sim-fill-purple { background: #8b5cf6; }
.succession-sim-fill-amber { background: #f59e0b; }
.succession-sim-fill-navy { background: #1a2744; }
.succession-sim-briefing {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-left: 4px solid #c9a84c;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}
.succession-sim-briefing-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
}
.succession-sim-briefing-icon {
    font-size: 1.2rem;
}
.succession-sim-briefing-header h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0;
}
.succession-sim-briefing-text {
    font-size: 0.88rem;
    line-height: 1.65;
    color: #374151;
}
.succession-sim-controls {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}
.succession-sim-controls h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 1px solid #e9ecef;
}
.succession-sim-controls-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 20px;
}
.succession-sim-control-full {
    grid-column: 1 / -1;
}
.succession-sim-control-group {
    display: flex;
    flex-direction: column;
}
.succession-sim-control-group label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #5a6c7d;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
}
.succession-sim-select,
.succession-sim-input {
    background: #f8f9fa;
    border: 1px solid #ced4da;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease;
    width: 100%;
    box-sizing: border-box;
}
.succession-sim-select:focus,
.succession-sim-input:focus {
    border-color: #1a2744;
    outline: none;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.1);
}
.succession-sim-range-container {
    display: flex;
    align-items: center;
    gap: 10px;
}
.succession-sim-range-min,
.succession-sim-range-max {
    font-size: 0.72rem;
    color: #6b7280;
    white-space: nowrap;
}
.succession-sim-range {
    flex: 1;
    -webkit-appearance: none;
    appearance: none;
    height: 6px;
    background: #e9ecef;
    border-radius: 3px;
    outline: none;
}
.succession-sim-range::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 18px;
    height: 18px;
    background: #1a2744;
    border-radius: 50%;
    cursor: pointer;
}
.succession-sim-range::-moz-range-thumb {
    width: 18px;
    height: 18px;
    background: #1a2744;
    border-radius: 50%;
    cursor: pointer;
    border: none;
}
.succession-sim-range-value {
    text-align: center;
    font-size: 0.8rem;
    color: #5a6c7d;
    margin-top: 4px;
    font-weight: 600;
}
.succession-sim-btn-group {
    display: flex;
    gap: 12px;
    align-items: center;
}
.succession-sim-btn-submit {
    background: #1a2744 !important;
    border-color: #1a2744 !important;
    padding: 10px 28px;
    font-weight: 600;
    font-size: 0.9rem;
    border-radius: 3px;
    transition: background 0.2s ease;
    color: #ffffff;
}
.succession-sim-btn-submit:hover {
    background: #2c3e6b !important;
    border-color: #2c3e6b !important;
}
.succession-sim-chart-section {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}
.succession-sim-chart-section h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 16px 0;
}
.succession-sim-chart-wrapper {
    position: relative;
    height: 280px;
}
.succession-sim-history {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    padding: 24px;
}
.succession-sim-history h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 16px 0;
}
.succession-sim-container .table {
    font-size: 0.82rem;
    color: #1a2744;
}
.succession-sim-container .table thead th {
    background: #f0f2f8;
    border-bottom: 2px solid #1a2744;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    color: #5a6c7d;
}
@media (max-width: 768px) {
    .succession-sim-container {
        padding: 16px;
    }
    .succession-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .succession-sim-controls-grid {
        grid-template-columns: 1fr;
    }
    .succession-sim-header h1 {
        font-size: 1.2rem;
    }
    .succession-sim-header {
        padding: 24px 20px;
    }
}

