(function() {
    'use strict';

    class SuccessionAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Toma de Decisiones Gerenciales';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefingKey: 'round1_briefing',
                    decisionLabelKey: 'round1_decision_label',
                    investmentLabelKey: 'round1_investment_label',
                    approachLabelKey: 'round1_approach_label',
                    investmentMax: 2000,
                    investmentDefault: 500,
                    options: [
                        { value: 'A', labelKey: 'round1_optA' },
                        { value: 'B', labelKey: 'round1_optB' },
                        { value: 'C', labelKey: 'round1_optC' },
                        { value: 'D', labelKey: 'round1_optD' },
                        { value: 'E', labelKey: 'round1_optE' }
                    ]
                },
                {
                    titleKey: 'round2_title',
                    briefingKey: 'round2_briefing',
                    decisionLabelKey: 'round2_decision_label',
                    investmentLabelKey: 'round2_investment_label',
                    approachLabelKey: 'round2_approach_label',
                    investmentMax: 1500,
                    investmentDefault: 400,
                    options: [
                        { value: 'operations', labelKey: 'round2_optOps' },
                        { value: 'strategy', labelKey: 'round2_optStrat' },
                        { value: 'balanced', labelKey: 'round2_optBal' },
                        { value: 'external', labelKey: 'round2_optExt' }
                    ]
                },
                {
                    titleKey: 'round3_title',
                    briefingKey: 'round3_briefing',
                    decisionLabelKey: 'round3_decision_label',
                    investmentLabelKey: 'round3_investment_label',
                    approachLabelKey: 'round3_approach_label',
                    investmentMax: 1000,
                    investmentDefault: 300,
                    options: [
                        { value: 'andres_lead', labelKey: 'round3_optAndres' },
                        { value: 'shared', labelKey: 'round3_optShared' },
                        { value: 'catalina_strat', labelKey: 'round3_optCatalina' },
                        { value: 'board_mediated', labelKey: 'round3_optBoard' }
                    ]
                },
                {
                    titleKey: 'round4_title',
                    briefingKey: 'round4_briefing',
                    decisionLabelKey: 'round4_decision_label',
                    investmentLabelKey: 'round4_investment_label',
                    approachLabelKey: 'round4_approach_label',
                    investmentMax: 1500,
                    investmentDefault: 500,
                    options: [
                        { value: 'negotiate', labelKey: 'round4_optNeg' },
                        { value: 'legal', labelKey: 'round4_optLegal' },
                        { value: 'accelerate', labelKey: 'round4_optAccel' },
                        { value: 'buyout', labelKey: 'round4_optBuyout' }
                    ]
                }
            ];
        }

        _lang(){try{if(window.vcI18n&&vcI18n.lang)return String(vcI18n.lang).substring(0,2)==='es'?'es':'en';}catch(e){}var l=(window.mySimulation&&(window.mySimulation.currentLanguage||window.mySimulation.language))||(document.documentElement&&document.documentElement.lang)||'en';return String(l).substring(0,2)==='es'?'es':'en';}
        _grade(gov,harm,mod){var g='Needs Improvement';if(gov>=60&&harm>=50)g='Good';if(gov>=75&&harm>=60&&mod>=50)g='Excellent';return g;}
        formatCompletionMessage(summary){var es=this._lang()==='es';var ov=(summary&&typeof summary.overallScore==='number')?summary.overallScore:(summary.governance||0);var perf=(summary&&summary.performance)||'';var tierMap=es?{'Needs Improvement':'Necesita Mejorar','Good':'Buena','Excellent':'Excelente'}:{};var perfL=tierMap[perf]||perf;var ins=(summary&&summary.insights)||[];var color=ov>=75?'#2e7d32':(ov>=60?'#f9a825':'#c62828');var kpis=es?[['Estabilidad',summary.stability],['Armonia',summary.harmony],['Modernizacion',summary.modernization],['Moral',summary.morale]]:[['Stability',summary.stability],['Harmony',summary.harmony],['Modernization',summary.modernization],['Morale',summary.morale]];var govL=es?'Gobernanza':'Governance';var thanks=es?'Gracias por participar.':'Thank you for participating.';var kpiRow=kpis.map(function(k){return '<span style="display:inline-block;margin:0 8px;"><strong>'+(k[1]||0)+'</strong> '+k[0]+'</span>';}).join('');var items=ins.map(function(t){return '<li>'+t+'</li>';}).join('');var insBlock=items?('<ul style="text-align:left;margin-top:12px;display:inline-block;">'+items+'</ul>'):'';return '<div class="completion-message text-center p-4">'+'<div style="font-size:2.6rem;font-weight:800;color:'+color+';">'+ov+'/100</div>'+'<p class="lead" style="margin:4px 0 2px;">'+govL+'</p>'+'<p style="font-weight:600;color:'+color+';">'+perfL+'</p>'+'<p class="text-muted" style="margin-bottom:6px;">'+kpiRow+'</p>'+insBlock+'<hr class="my-3"><p class="text-muted">'+thanks+'</p></div>';}
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    stability: 65,
                    harmony: 40,
                    modernization: 30,
                    morale: 70,
                    governance: 51,
                    cash: 15000,
                    stabilityHistory: [],
                    harmonyHistory: [],
                    modernizationHistory: [],
                    moraleHistory: [],
                    governanceHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primaryDecision: 'A',
                    investmentAmount: 500,
                    approachStyle: 5
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {

            var selectEl = document.getElementById('primaryDecision');
            if (selectEl) decisions.primaryDecision = selectEl.value;

            var investEl = document.getElementById('investmentAmount');
            if (investEl) decisions.investmentAmount = parseInt(investEl.value);

            var approachEl = document.getElementById('approachStyle');
            if (approachEl) decisions.approachStyle = parseInt(approachEl.value);

            var roundIdx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            if (!decisions.primaryDecision) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_warning'), 'warning'
                );
                return false;
            }

            if (isNaN(decisions.investmentAmount) || decisions.investmentAmount < 0 || decisions.investmentAmount > round.investmentMax) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('investment_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var stabDelta = 0, harmDelta = 0, modDelta = 0, moraleDelta = 0;
            var investFactor = Math.min(d.investmentAmount / round.investmentMax, 1);
            var approachFactor = d.approachStyle / 10;

            if (roundIdx === 0) {
                switch (d.primaryDecision) {
                    case 'A':
                        stabDelta = 15; harmDelta = -20; modDelta = -10; moraleDelta = 10;
                        break;
                    case 'B':
                        stabDelta = -15; harmDelta = -10; modDelta = 20; moraleDelta = -15;
                        break;
                    case 'C':
                        stabDelta = -5; harmDelta = 5; modDelta = 10; moraleDelta = -5;
                        break;
                    case 'D':
                        stabDelta = 5; harmDelta = 10; modDelta = 15; moraleDelta = -10;
                        break;
                    case 'E':
                        stabDelta = -25; harmDelta = -15; modDelta = 0; moraleDelta = -30;
                        break;
                }
                harmDelta += Math.round(investFactor * 8);
                moraleDelta += Math.round(investFactor * 5);
                harmDelta += Math.round(approachFactor * 6);
                stabDelta += Math.round((1 - approachFactor) * 4);
            } else if (roundIdx === 1) {
                switch (d.primaryDecision) {
                    case 'operations':
                        stabDelta = 10; harmDelta = -5; modDelta = -5; moraleDelta = 8;
                        break;
                    case 'strategy':
                        stabDelta = -5; harmDelta = 5; modDelta = 15; moraleDelta = -3;
                        break;
                    case 'balanced':
                        stabDelta = 5; harmDelta = 8; modDelta = 8; moraleDelta = 3;
                        break;
                    case 'external':
                        stabDelta = 3; harmDelta = 3; modDelta = 12; moraleDelta = -8;
                        break;
                }
                modDelta += Math.round(investFactor * 10);
                harmDelta += Math.round(approachFactor * 5);
            } else if (roundIdx === 2) {
                switch (d.primaryDecision) {
                    case 'andres_lead':
                        stabDelta = 8; harmDelta = -12; modDelta = -5; moraleDelta = 5;
                        break;
                    case 'shared':
                        stabDelta = 2; harmDelta = 10; modDelta = 8; moraleDelta = 2;
                        break;
                    case 'catalina_strat':
                        stabDelta = -3; harmDelta = 6; modDelta = 12; moraleDelta = -2;
                        break;
                    case 'board_mediated':
                        stabDelta = 5; harmDelta = 12; modDelta = 10; moraleDelta = -3;
                        break;
                }
                harmDelta += Math.round(investFactor * 8);
                harmDelta += Math.round(approachFactor * 7);
                moraleDelta += Math.round(approachFactor * 4);
            } else {
                switch (d.primaryDecision) {
                    case 'negotiate':
                        stabDelta = 3; harmDelta = 8; modDelta = 5; moraleDelta = 5;
                        break;
                    case 'legal':
                        stabDelta = 5; harmDelta = -20; modDelta = -5; moraleDelta = -8;
                        break;
                    case 'accelerate':
                        stabDelta = -5; harmDelta = 5; modDelta = 10; moraleDelta = 2;
                        break;
                    case 'buyout':
                        stabDelta = 8; harmDelta = -5; modDelta = 0; moraleDelta = 3;
                        break;
                }
                stabDelta += Math.round(investFactor * 6);
                harmDelta += Math.round(approachFactor * 8);
            }

            ds.stability = Math.max(0, Math.min(100, ds.stability + stabDelta));
            ds.harmony = Math.max(0, Math.min(100, ds.harmony + harmDelta));
            ds.modernization = Math.max(0, Math.min(100, ds.modernization + modDelta));
            ds.morale = Math.max(0, Math.min(100, ds.morale + moraleDelta));
            ds.cash -= d.investmentAmount;
            ds.governance = Math.round((ds.stability * 0.25 + ds.harmony * 0.25 + ds.modernization * 0.25 + ds.morale * 0.25));

            ds.stabilityHistory.push(ds.stability);
            ds.harmonyHistory.push(ds.harmony);
            ds.modernizationHistory.push(ds.modernization);
            ds.moraleHistory.push(ds.morale);
            ds.governanceHistory.push(ds.governance);
            ds.score = ds.governance;
            ds.performance = { overallScore: ds.governance, grade: this._grade(ds.governance, ds.harmony, ds.modernization) };


            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                primaryDecision: d.primaryDecision,
                investmentAmount: d.investmentAmount,
                approachStyle: d.approachStyle,
                stability: ds.stability,
                harmony: ds.harmony,
                modernization: ds.modernization,
                morale: ds.morale,
                governance: ds.governance,
                cash: ds.cash,
                overallScore: ds.governance,
                score: ds.governance
            };
        }

        _updateBars(ds) {
            var bars = [
                { id: 'stabilityBar', val: ds.stability },
                { id: 'harmonyBar', val: ds.harmony },
                { id: 'modernizationBar', val: ds.modernization },
                { id: 'moraleBar', val: ds.morale },
                { id: 'governanceBar', val: ds.governance }
            ];
            for (var i = 0; i < bars.length; i++) {
                var el = document.getElementById(bars[i].id);
                if (el) el.style.width = bars[i].val + '%';
            }
        }

        _updateBriefing(state) {
            if ((state.currentPeriod || 1) > this.ROUNDS.length) {
                var _cc = document.querySelector('.succession-sim-controls'); if (_cc) _cc.style.display = 'none';
                var _es = this._lang() === 'es';
                var _bt = document.getElementById('briefingTitle'); if (_bt) _bt.textContent = _es ? 'Sucesion completada' : 'Succession complete';
                var _b = document.getElementById('briefingText'); if (_b) _b.innerHTML = _es ? '<strong>Proceso de sucesion completado.</strong> Has finalizado las 4 rondas. Revisa tu puntuacion y el resumen final.' : '<strong>Succession process complete.</strong> You have finished all 4 rounds. Review your score and final summary.';
                if (state.domainState) this._updateBars(state.domainState);
                return;
            }
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) briefEl.innerHTML = window.mySimulation.t(round.briefingKey);

            var briefTitle = document.getElementById('briefingTitle');
            if (briefTitle && window.mySimulation) briefTitle.textContent = window.mySimulation.t(round.titleKey);

            var selectEl = document.getElementById('primaryDecision');
            if (selectEl && window.mySimulation) {
                selectEl.innerHTML = '';
                for (var i = 0; i < round.options.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = round.options[i].value;
                    opt.textContent = window.mySimulation.t(round.options[i].labelKey);
                    selectEl.appendChild(opt);
                }
            }

            var investEl = document.getElementById('investmentAmount');
            if (investEl) {
                investEl.max = round.investmentMax;
                investEl.value = round.investmentDefault;
            }

            var primaryLabel = document.getElementById('primaryDecisionLabel');
            if (primaryLabel && window.mySimulation) primaryLabel.textContent = window.mySimulation.t(round.decisionLabelKey);

            var investLabel = document.getElementById('investmentLabel');
            if (investLabel && window.mySimulation) investLabel.textContent = window.mySimulation.t(round.investmentLabelKey);

            var approachLabel = document.getElementById('approachLabel');
            if (approachLabel && window.mySimulation) approachLabel.textContent = window.mySimulation.t(round.approachLabelKey);

            if (state.domainState) this._updateBars(state.domainState);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('stabilityDisplay', 'domainState.stability', function(v) { return Math.round(v); });
            uiManager.bind('harmonyDisplay', 'domainState.harmony', function(v) { return Math.round(v); });
            uiManager.bind('modernizationDisplay', 'domainState.modernization', function(v) { return Math.round(v); });
            uiManager.bind('moraleDisplay', 'domainState.morale', function(v) { return Math.round(v); });
            uiManager.bind('governanceDisplay', 'domainState.governance', function(v) { return Math.round(v); });

            var rangeEl = document.getElementById('approachStyle');
            var rangeValEl = document.getElementById('approachValue');
            if (rangeEl && rangeValEl) {
                rangeEl.addEventListener('input', function() {
                    rangeValEl.textContent = rangeEl.value;
                });
            }
        }

        getChartConfig() {
            return {
                kpiChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Stability',
                                data: [],
                                borderColor: '#3b82f6',
                                backgroundColor: 'rgba(59,130,246,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 5,
