        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var r = lastRecord.results || {};
            var gov = r.governance || 0;
            var stab = r.stability || 0;
            var harm = r.harmony || 0;
            var mod = r.modernization || 0;
            var mor = r.morale || 0;

            var performance = this._grade(gov, harm, mod);

            var __es = this._lang() === 'es';
            var insights = [];
            if (harm < 40) insights.push(__es ? 'La armonia familiar se mantuvo baja: el plan de sucesion podria enfrentar resistencia continua.' : 'Family harmony remained low — the succession plan may face ongoing resistance.');
            if (mod >= 60) insights.push(__es ? 'Fuerte trayectoria de modernizacion: la empresa esta posicionada para crecer.' : 'Strong modernization trajectory — the company is positioned for growth.');
            if (stab >= 70 && mor >= 60) insights.push(__es ? 'La estabilidad organizacional y la moral son solidas: buena base para la transicion.' : 'Organizational stability and morale are solid — good foundation for transition.');
            if (gov >= 70) insights.push(__es ? 'La puntuacion general de gobernanza es fuerte: toma de decisiones equilibrada en todo momento.' : 'Overall governance score is strong — balanced decision-making throughout.');
            if (insights.length === 0) insights.push(__es ? 'Considera como las distintas estructuras de sucesion afectan a todos los interesados por igual.' : 'Consider how different succession structures affect all stakeholders equally.');

            return {
                governance: gov,
                stability: stab,
                harmony: harm,
                modernization: mod,
                morale: mor,
                performance: performance,
                overallScore: gov,
                score: gov,
                insights: insights
            };
        }

